/** Evaluation-only adapter. NEVER import into production receiver.
 * Truth, beta, X and noise enter here; only Y/array/knownM/domain go to receiver.
 */
import {SOURCE_ARRAY,LIMITS} from './receiver.mjs';
export function seededNormal(seed){if(!Number.isInteger(seed)||seed<0||seed>0xffffffff)throw new Error('seed must be uint32');let state=seed>>>0,spare=null;const uniform=()=>{state=(state+0x6D2B79F5)>>>0;let t=state;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;};return ()=>{if(spare!==null){const v=spare;spare=null;return v;}const u=Math.max(uniform(),1/4294967296),v=uniform(),a=Math.sqrt(-2*Math.log(u)),b=2*Math.PI*v;spare=a*Math.sin(b);return a*Math.cos(b);};}
export function generateObservation({X,array=SOURCE_ARRAY,truthXY,beta,noiseVariance,seed,planeWave=false}){const n=array.n,t=X.columns;if(!(Number.isFinite(array.apertureM)&&array.apertureM>0&&array.apertureM<=10&&Number.isFinite(array.wavelengthM)&&array.wavelengthM>=1e-6&&array.wavelengthM<=10))throw new Error('Invalid physical array constants');if(!Number.isInteger(n)||n<2||n>LIMITS.maxN||X.rows!==n||!Number.isInteger(t)||t<2||t>LIMITS.maxT||n*t>LIMITS.maxSamples||!(X.data instanceof Float64Array)||X.data.length!==2*n*t)throw new Error('Invalid X shape');if(!truthXY||truthXY.length!==2||!truthXY.every(Number.isFinite)||Math.hypot(...truthXY)===0)throw new Error('Nonzero finite truth required in generator only');if(!beta||beta.length!==2||!beta.every(Number.isFinite)||!Number.isFinite(noiseVariance)||noiseVariance<0)throw new Error('Invalid generation constants');const a=new Float64Array(2*n),r=Math.hypot(...truthXY),k=2*Math.PI/array.wavelengthM;for(let i=0;i<n;i++){const q=(i-(n-1)/2)*array.apertureM/(n-1),rn=Math.hypot(truthXY[0]-q,truthXY[1]),phase=planeWave?k*q*truthXY[0]/r:-k*(q*q-2*truthXY[0]*q)/(rn+r);a[2*i]=Math.cos(phase);a[2*i+1]=Math.sin(phase);}const s=new Float64Array(2*t);for(let j=0;j<t;j++)for(let i=0;i<n;i++){const p=2*(i*t+j),xr=X.data[p],xi=X.data[p+1];if(!Number.isFinite(xr)||!Number.isFinite(xi))throw new Error('X not finite');s[2*j]+=a[2*i]*xr-a[2*i+1]*xi;s[2*j+1]+=a[2*i]*xi+a[2*i+1]*xr;}
 const y=new Float64Array(2*n*t),noise=new Float64Array(y.length),normal=seededNormal(seed),sd=Math.sqrt(noiseVariance/2);for(let i=0;i<n;i++){const br=beta[0]*a[2*i]-beta[1]*a[2*i+1],bi=beta[0]*a[2*i+1]+beta[1]*a[2*i];for(let j=0;j<t;j++){const p=2*(i*t+j);noise[p]=sd*normal();noise[p+1]=sd*normal();y[p]=br*s[2*j]-bi*s[2*j+1]+noise[p];y[p+1]=br*s[2*j+1]+bi*s[2*j]+noise[p+1];}}
 return {Y:{data:y,rows:n,columns:t},noise};}
/** Fixed orthogonal DFT component sequences: X X^H/T = F F^H.
 * An explicit alternative to the reference's seeded QR sequence, not iid symbols.
 */
export function waveformFromFactor(F,T){const n=F.rows,k=F.columns;if(!Number.isInteger(T)||T<2||!Number.isInteger(n)||!Number.isInteger(k)||n<2||n>LIMITS.maxN||k<1||k>T||T>LIMITS.maxT||n*T>LIMITS.maxSamples||!(F.data instanceof Float64Array)||F.data.length!==2*n*k)throw new Error('Invalid factor or T');const x=new Float64Array(2*n*T);for(let t=0;t<T;t++)for(let j=0;j<k;j++){const phase=2*Math.PI*j*t/T,sr=Math.cos(phase),si=Math.sin(phase);for(let i=0;i<n;i++){const f=2*(i*k+j),p=2*(i*T+t);if(!Number.isFinite(F.data[f])||!Number.isFinite(F.data[f+1]))throw new Error('Nonfinite factor');x[p]+=F.data[f]*sr-F.data[f+1]*si;x[p+1]+=F.data[f]*si+F.data[f+1]*sr;}}return {data:x,rows:n,columns:T};}
